package com.tekwatt.billing.dto;import com.tekwatt.billing.entity.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;public record BillResponse(UUID id,UUID tenantId,UUID userId,UUID sessionId,UUID tariffId,String billNumber,BigDecimal energyKwh,Long durationMinutes,BigDecimal energyAmount,BigDecimal timeAmount,BigDecimal sessionFee,BigDecimal subtotal,BigDecimal taxPercent,BigDecimal taxAmount,BigDecimal totalAmount,String currency,BillStatus status,Instant createdAt,Instant paidAt,Instant updatedAt){public static BillResponse from(Bill b){return new BillResponse(b.getId(),b.getTenantId(),b.getUserId(),b.getSessionId(),b.getTariffId(),b.getBillNumber(),b.getEnergyKwh(),b.getDurationMinutes(),b.getEnergyAmount(),b.getTimeAmount(),b.getSessionFee(),b.getSubtotal(),b.getTaxPercent(),b.getTaxAmount(),b.getTotalAmount(),b.getCurrency(),b.getStatus(),b.getCreatedAt(),b.getPaidAt(),b.getUpdatedAt());}}
